      "blocking": false,
      "owner": "domain expert"
    }
  ],
  "system": {
    "name": "Meal-kit subscription",
    "one_liner": "Weekly meal kits delivered to subscribers",
    "problem": "Busy households want to cook without planning",
    "why_now": "Demand for home cooking"
  },
  "business_model": {
    "customer_segments": [
      "Busy households"
    ],
    "value_propositions": [
      "Pre-portioned weekly meals"
    ],
    "channels": [
      "Web app"
    ],
    "customer_relationships": [
      "Self-service"
    ],
    "revenue_streams": [
      "Weekly subscription fee"
    ],
    "key_resources": [
      "Recipe library",
      "Cold chain"
    ],
    "key_activities": [
      "Menu planning",
      "Packing",
      "Delivery"
    ],
    "key_partners": [
      "Courier"
    ],
    "cost_structure": [
      "Ingredients",
      "Logistics"
    ],
    "value_proposition_links": [
      {
        "value_proposition": "Pre-portioned weekly meals",
        "capabilities": [
          "cap-menu-planning",
          "cap-fulfilment"
        ],
        "beats": [
          "alt-supermarket-shop"
        ]
      }
    ]
  },
  "goals": [
    {
      "id": "G1",
      "statement": "Grow active subscribers",
      "metric": "active subscriptions",
      "target": "10k",
      "horizon": "12 months"
    }
  ],
  "actors": [
    {
      "id": "subscriber",
      "name": "Subscriber",
      "kind": "person",
      "description": "Household receiving boxes",
      "goals": [
        "G1"
      ]
    },
    {
      "id": "packer",
      "name": "Packer",
      "kind": "person",
      "description": "Warehouse staff",
      "goals": []
    }
  ],
  "impacts": [
    {
      "id": "I1",
      "actor": "subscriber",
      "change": "Chooses meals in under two minutes a week",
      "goal": "G1"
    }
  ],
  "deliverables": [
    {
      "id": "D1",
      "impact": "I1",
      "description": "Weekly menu selection",
      "priority": "must"
    }
  ],
  "capabilities": [
    {
      "id": "cap-subscription-management",
      "name": "Subscription management",
      "description": "Sign up, pause, cancel",
      "evolution": "product"
    },
    {
      "id": "cap-menu-planning",
      "name": "Menu planning",
      "description": "Weekly menu and choices",
      "evolution": "custom"
    },
    {
      "id": "cap-fulfilment",
      "name": "Fulfilment",
      "description": "Pack and ship boxes",
      "evolution": "custom"
    }
  ],
  "constraints": [
    {
      "id": "C1",
      "kind": "regulatory",
      "text": "Food safety labelling"
    }
  ],
  "non_goals": [
    "Restaurant delivery"
  ],
  "existing_systems": [
    {
      "name": "Stripe",
      "role": "payments",
      "will": "integrate"
    }
  ],
  "scale_target": {
    "deployables_min": 1,
    "deployables_max": 3,
    "teams": 1,
    "users": "10k",
    "notes": "solo dev"
  },
  "notes_for_downstream": [
    {
      "id": "N1",
      "text": "'Box' means the week's menu choice to subscribers but the packed parcel to packers — treat as a boundary, not a synonym",
      "for": [
        "discover",
        "decompose"
      ],
      "kind": "language"
    }
  ],
  "plain_words": {
    "what": "We wrote down who this is for, what counts as working, and how big it is allowed to get.",
    "decided": "One product: a weekly meal-kit box people subscribe to. Success is measured by weeks kept, not sign-ups.",
    "assumed": "One person builds and runs the whole thing, so it must stay small enough for one head.",
    "riskiest": "If a second team ever joins, almost every sizing call below was made for the wrong shape of team."
  },
  "alternatives": [
    {
      "id": "alt-supermarket-shop",
      "name": "Weekly supermarket shop and own recipes",
      "kind": "manual-process",
      "used_by": [
        "subscriber"
      ],
      "strengths": "Cheap, flexible, no commitment",
      "weaknesses": "Planning and portioning take an evening a week; waste",
      "capabilities": [
        "cap-menu-planning"
      ]
    },
    {
      "id": "alt-rival-mealkit",
      "name": "Incumbent national meal-kit brand",
      "kind": "competitor",
      "used_by": [
        "subscriber"
      ],
      "strengths": "Known brand, wide menu",
      "weaknesses": "Rigid weekly cut-off, poor swaps and pauses",
      "capabilities": [
        "cap-subscription-management",
        "cap-menu-planning",
        "cap-fulfilment"
      ]
    }
  ]
}

{
  "schema_version": 1,
  "step": "discover",
  "produced_by": "ddd-discover",
  "produced_at": "<TS>",
  "mode": "auto",
  "depth": "light",
  "inputs": [
    "ddd/01-understand/understand.json"
  ],
  "assumptions": [
    {
      "id": "A1",
      "text": "Example fixture; assumptions are illustrative",
      "confidence": "high"
    }
  ],
  "open_questions": [
    {
      "id": "Q1",
      "text": "Illustrative open question",
      "blocking": false,
      "owner": "domain expert"
    }
  ],
  "plain_words": {
    "what": "We walked the story of a week, in order, and wrote down every moment something happens.",
    "decided": "5 events, from a household picking meals to a box going out. Two of them are the ones the business is paid for.",
    "assumed": "Nothing goes wrong: no refunds, no missed deliveries, no card failures on the timeline yet.",
    "riskiest": "The failure paths are where most real work hides. Adding them later can move a boundary we set below."
  },
  "actors": [
    {
      "id": "subscriber",
      "name": "Subscriber",
      "from_understand": "subscriber"
    },
    {
      "id": "packer",
      "name": "Packer",
      "from_understand": "packer"
    }
  ],
  "external_systems": [
    {
      "id": "stripe",
      "name": "Stripe",
      "description": "Payments"
    },
    {
      "id": "courier",
      "name": "Courier",
      "description": "Delivery partner"
    }
  ],
  "phases": [
    {
      "id": "subscribing",
      "name": "Subscribing",
      "order": 1
    },
    {
      "id": "choosing",
      "name": "Choosing meals",
      "order": 2
    },
    {
      "id": "fulfilling",
      "name": "Fulfilling",
      "order": 3
    }
  ],
  "events": [
    {
      "id": "subscription-started",
      "name": "Subscription Started",
      "phase": "subscribing",
      "sequence": 10,
      "actor": "subscriber",
      "triggered_by": "start-subscription",
      "pivotal": true,
      "data": [
        "subscriptionId"
      ],
      "description": "Customer became a subscriber"
    },
    {
      "id": "meals-chosen",
      "name": "Meals Chosen",
      "phase": "choosing",
      "sequence": 20,
      "actor": "subscriber",
      "triggered_by": "choose-meals",
      "pivotal": false,
      "data": [
        "subscriptionId",
        "week",
        "recipeIds"
      ],
      "description": "Weekly choice locked in"
    },
    {
      "id": "week-charged",
      "name": "Week Charged",
      "phase": "choosing",
      "sequence": 25,
      "actor": "stripe",
      "triggered_by": "charge-week",
      "pivotal": false,
      "data": [
        "subscriptionId",
        "week",
        "amount"
      ],
      "description": "Payment taken"
    },
    {
      "id": "box-packed",
      "name": "Box Packed",
      "phase": "fulfilling",
      "sequence": 30,
      "actor": "packer",
      "triggered_by": "pack-box",
      "pivotal": true,
      "data": [
        "boxId"
      ],
      "description": "Physical box ready"
    },
    {
      "id": "box-shipped",
      "name": "Box Shipped",
      "phase": "fulfilling",
      "sequence": 40,
      "actor": "courier",
      "triggered_by": "ship-box",
      "pivotal": true,
      "data": [
        "boxId",
        "tracking"
      ],
      "description": "Handed to courier"
    }
  ],
  "commands": [
    {
      "id": "start-subscription",
      "name": "Start Subscription",
      "actor": "subscriber",
      "produces": [
        "subscription-started"
      ],
      "description": ""
    },
    {
      "id": "choose-meals",
      "name": "Choose Meals",
      "actor": "subscriber",
      "produces": [
        "meals-chosen"
      ],
      "description": ""
    },
    {
      "id": "charge-week",
      "name": "Charge Week",
      "actor": null,
      "produces": [
        "week-charged"
      ],
      "description": ""
    },
    {
      "id": "pack-box",
      "name": "Pack Box",
      "actor": "packer",
      "produces": [
        "box-packed"
      ],
      "description": ""
    },
    {
      "id": "ship-box",
      "name": "Ship Box",
      "actor": "packer",
      "produces": [
        "box-shipped"
      ],
      "description": ""
    },
    {
      "id": "charge-card",
      "name": "Charge Card",
      "actor": null,
      "produces": [],
      "description": "Billing asks the payment provider to charge the subscriber's card for the week"
    }
  ],
  "policies": [
    {
      "id": "charge-on-choice",
      "name": "Whenever meals chosen, charge the week",
      "when": "meals-chosen",
      "then": [
        "charge-week"
      ],
      "kind": "automatic"
    },
    {
      "id": "pack-on-charge",
      "name": "Whenever week charged, pack box",
      "when": "week-charged",
      "then": [
        "pack-box"
      ],
      "kind": "automatic"
    }
  ],
  "read_models": [
    {
      "id": "weekly-menu",
      "name": "Weekly menu",
      "informs": "choose-meals",
      "used_by": "subscriber"
    }
  ],
  "aggregate_candidates": [
    {
      "id": "subscription",
      "name": "Subscription",
      "handles": [
        "start-subscription",
        "choose-meals"
      ],
      "emits": [
        "subscription-started",
        "meals-chosen"
      ]
    },
    {
      "id": "box",
      "name": "Box",
      "handles": [
        "pack-box",
        "ship-box"
      ],
      "emits": [
        "box-packed",
        "box-shipped"
      ]
    }
  ],
  "pivotal_events": [
    "subscription-started",
    "box-packed",
    "box-shipped"
  ],
  "hotspots": [
    {
      "id": "H1",
      "text": "What happens if payment fails after meals are chosen?",
      "near": "week-charged",
      "kind": "unclear"
    }
  ],
  "scenarios": [
    {
      "id": "S1",
      "name": "Happy path weekly box",
      "actors": [
        "subscriber",
        "packer"
      ],
      "events": [
        "meals-chosen",
        "week-charged",
        "box-packed",
        "box-shipped"
      ]
    }
  ],
  "glossary": [
    {
      "term": "Subscription",
      "definition": "A customer's standing weekly order",
      "avoid": [
        "plan",
        "membership"
      ],
      "context": null
    },
    {
      "term": "Box",
      "definition": "One week's delivery for one subscription",
      "avoid": [
        "order",
        "shipment"
      ],
      "context": null
    }
  ]
}
